SELECT s.id FROM salary_summary s INNER JOIN salary_period p ON s.period_id = p.id
s.delete_flag = 0 AND p.employee_id = #{employeeId} AND p.settlement_month = #{settlementMonth}
LIMIT 1

SELECT s.*, p.settlement_month AS settlementMonth, p.employee_id AS employeeId, e.employee_code AS employeeCode, e.employee_name AS employeeName FROM salary_summary s INNER JOIN salary_period p ON s.period_id = p.id LEFT JOIN salary_employee e ON p.employee_id = e.id
s.delete_flag = 0
AND p.employee_id = #{req.employeeId}
AND p.settlement_month = #{req.settlementMonth}
AND s.period_id = #{req.periodId}
ORDER BY s.create_time DESC

SELECT s.*, p.settlement_month AS settlementMonth, p.employee_id AS employeeId, e.employee_code AS employeeCode, e.employee_name AS employeeName FROM salary_summary s INNER JOIN salary_period p ON s.period_id = p.id LEFT JOIN salary_employee e ON p.employee_id = e.id
s.delete_flag = 0 AND s.id = #{id}
LIMIT 1
